public void testBlockApiHandle() {
    TestGraph<LongWritable, LongWritable, NullWritable> graph = createTestGraph();
    final BlockApiHandle handle = new BlockApiHandle();
    final DefaultParentPiece piece = new TestPiece(new DummyObjectWithApiHandle(handle));
    Block block = new BlockWithApiHandle() {

        @Override
