@Test
public void testStartCustom() {
    NumericTestGraph<LongWritable, LongWritable, NullWritable> graph = createTestGraph();
    Block reply = SendMessageChain.<LongWritable, LongWritable, NullWritable, LongWritable>startCustom(// Sends ID to it's first neighbor, passing max of received messages to next part of the chain
    (consumer) -> new Piece<LongWritable, LongWritable, NullWritable, LongWritable, Object>() {

        @Override
        public VertexSender<LongWritable, LongWritable, NullWritable> getVertexSender(BlockWorkerSendApi<LongWritable, LongWritable, NullWritable, LongWritable> workerApi, Object executionStage) {
            return (vertex) -> {
                Edge<LongWritable, NullWritable> edge = Iterators.getNext(vertex.getEdges().iterator(), null);
                if (edge != null) {
                    workerApi.sendMessage(edge.getTargetVertexId(), vertex.getId());
                }
            };
        }

        @Override
        public VertexReceiver<LongWritable, LongWritable, NullWritable, LongWritable> getVertexReceiver(BlockWorkerReceiveApi<LongWritable> workerApi, Object executionStage) {
            return (vertex, messages) -> {
                consumer.apply(vertex, new LongWritable(max(messages)));
            };
        }

        @Override
        protected Class<LongWritable> getMessageClass() {
            return LongWritable.class;
        }
    }).thenSendToNeighbors("SendMaxIReceivedToAllNeighbors", SumMessageCombiner.LONG, (vertex, message) -> message).endConsume((vertex, message) -> vertex.getValue().set(message != null ? message.get() : 0));
    LocalBlockRunner.runBlock(graph.getTestGraph(), reply, new Object());
    Assert.assertEquals(3, graph.getVertex(1).getValue().get());
    Assert.assertEquals(2, graph.getVertex(2).getValue().get());
    Assert.assertEquals(3, graph.getVertex(3).getValue().get());
    Assert.assertEquals(0, graph.getVertex(4).getValue().get());
}

