@Test
public void testHeap() {
    int heapCapacity = 5;
    FixedCapacityIntByteMinHeap heap = new FixedCapacityIntByteMinHeap(heapCapacity);
    int[] keys = new int[] { 0, 1, 0, 10, 20, 0, 3, 4 };
    byte[] values = new byte[] { (byte) 0, (byte) 1, (byte) 2, (byte) 2, (byte) 2, (byte) 3, (byte) 3, (byte) 4 };
    List<Integer> positions = new ArrayList<>();
    for (int i = 0; i < keys.length; i++) {
        positions.add(i);
    }
    Collections.shuffle(positions);
    for (Integer position : positions) {
        heap.add(keys[position], values[position]);
    }
    for (int i = keys.length - heapCapacity; i < keys.length; i++) {
        Assert.assertEquals(heap.size(), heapCapacity);
