@Test
public void testLargeByteArrays() throws IOException {
    ImmutableClassesGiraphConfiguration conf = new ImmutableClassesGiraphConfiguration(new Configuration());
    BigDataOutput output = new BigDataOutput(conf);
    byte[] byteArray1 = new byte[(1 << 28) + 3];
    int pos1 = (1 << 27) + 2;
    byteArray1[pos1] = 17;
    output.write(byteArray1);
    Assert.assertEquals(9, output.getNumberOfDataOutputs());
    byte[] byteArray2 = new byte[(1 << 27) - 1];
    int pos2 = (1 << 26) + 5;
    byteArray2[pos2] = 13;
    output.write(byteArray2);
    Assert.assertEquals(13, output.getNumberOfDataOutputs());
    BigDataInput in = new BigDataInput(output);
    byte[] byteArray3 = new byte[byteArray1.length];
    in.readFully(byteArray3);
    Assert.assertEquals(byteArray1[pos1], byteArray3[pos1]);
    byte[] byteArray4 = new byte[byteArray2.length];
    in.readFully(byteArray4);
    Assert.assertEquals(byteArray2[pos2], byteArray4[pos2]);
}

@Test
public void testProgressableUtils() throws NoSuchFieldException, IllegalAccessException {
    final int sleepTime = 1800;
    final int msecPeriod = 500;
    ExecutorService executor = Executors.newFixedThreadPool(1);
    executor.submit(new Runnable() {

        @Override
        public void run() {
            try {
                Thread.sleep(sleepTime);
            } catch (InterruptedException e) {
                throw new IllegalStateException();
            }
        }
    });
    executor.shutdown();
    CountProgressable countProgressable = new CountProgressable();
    ProgressableUtils.awaitExecutorTermination(executor, countProgressable, msecPeriod);
    Assert.assertTrue(countProgressable.counter >= sleepTime / msecPeriod);
    Assert.assertTrue(countProgressable.counter <= (sleepTime + msecPeriod) / msecPeriod);
}

